const queryClient = new QueryClient();
const money = (value: number): string => `${value.toLocaleString('fr-FR')} $US`;
const dateLabel = (date: string): string => new Intl.DateTimeFormat('fr-FR', { day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit', timeZone: 'Africa/Bujumbura' }).format(new Date(date));
const relativeDeadline = (date: string, timestamp = Date.now()): string => {
  const diff = new Date(date).getTime() - timestamp;
  if (diff <= 0) return 'Terminée';
  const hours = Math.floor(diff / 3600000);
  const minutes = Math.floor((diff % 3600000) / 60000);
  return hours ? `${hours} h ${String(minutes).padStart(2, '0')} min` : `${minutes} min`;
};
function useCountdown(): number {
  const [timestamp, setTimestamp] = useState(Date.now());
  useEffect(() => { const timer = window.setInterval(() => setTimestamp(Date.now()), 1000); return () => window.clearInterval(timer); }, []);
  return timestamp;
}
const iconMap: Record<string, ComponentType<{ className?: string }>> = { smartphone: Smartphone, shirt: Shirt, lamp: LampDesk, medal: Medal, 'car-front': CarFront, palette: Palette, headphones: Headphones };

// Load categories from API
const useCategories = () => {
  const [categories, setCategories] = useState<any[]>([]);
  useEffect(() => {
    categoriesApi.list().then(setCategories).catch(() => setCategories([]));
  }, []);
  return categories;
};

