function CategoryRow() {
  const [, setLocation] = useLocation();
  const categories = useCategories();
  return <div className="mx-auto grid max-w-[1180px] grid-cols-4 gap-3 px-4 py-9 sm:grid-cols-7 sm:px-8">{categories.map((category) => { const Icon = iconMap[category.icon] ?? Tag; return <button key={category.id} onClick={() => setLocation(`/search?category=${category.id}`)} className="group flex flex-col items-center gap-2 text-center" data-testid={`button-category-${category.id}`}><span className="grid h-14 w-14 place-items-center rounded-2xl border border-border bg-card text-primary shadow-sm transition group-hover:-translate-y-1 group-hover:border-primary/40 group-hover:bg-primary group-hover:text-primary-foreground"><Icon className="h-6 w-6" /></span><span className="text-xs font-semibold">{category.name}</span></button>; })}</div>;
}

function ProductCard({ product, compact = false }: { product: Product; compact?: boolean }) {
  const [liked, setLiked] = useState(false);
  const timestamp = useCountdown();
  const remaining = new Date(product.endsAt).getTime() - timestamp;
  const expired = remaining <= 0 || product.status !== 'active';
  const urgent = !expired && remaining < 3600000;
  return <Link href={`/product/${product.id}`} className={`group block ${compact ? '' : 'animate-rise'}`} data-testid={`card-product-${product.id}`}>
    <div className="relative overflow-hidden rounded-2xl bg-muted">
      <img src={product.images[0]} alt={product.title} className={`${compact ? 'aspect-[1.15]' : 'aspect-[1.08]'} w-full object-cover transition duration-500 group-hover:scale-105`} data-testid={`img-product-${product.id}`} />
      <div className="absolute left-3 top-3 flex gap-2"><span className="rounded-full bg-[#f9f6ef]/90 px-2.5 py-1 text-[10px] font-bold uppercase tracking-[0.1em]">{product.category.name}</span>{expired ? <span className="rounded-full bg-muted px-2.5 py-1 text-[10px] font-bold">Terminée</span> : urgent && <span className="rounded-full bg-secondary px-2.5 py-1 text-[10px] font-bold">Bientôt fini</span>}</div>
      <span role="button" tabIndex={0} onClick={(event) => { event.preventDefault(); setLiked((value) => !value); }} onKeyDown={(event) => { if (event.key === 'Enter') { event.preventDefault(); setLiked((value) => !value); } }} className="absolute right-3 top-3 grid h-8 w-8 place-items-center rounded-full bg-[#f9f6ef]/90 transition hover:scale-110" data-testid={`button-favorite-${product.id}`} aria-label="Ajouter aux favoris"><Heart className={`h-4 w-4 ${liked ? 'fill-secondary text-secondary' : ''}`} /></span>
    </div>
    <div className="pt-3">
      <div className="mb-1 flex items-start justify-between gap-3"><h3 className="font-display text-[17px] font-bold leading-tight">{product.title}</h3><span className="shrink-0 pt-1 text-[11px] font-semibold text-muted-foreground">{product.city}</span></div>
      <div className="mt-3 flex items-end justify-between"><div><p className="text-[10px] font-bold uppercase tracking-[0.13em] text-muted-foreground">Enchère actuelle</p><p className="text-lg font-bold text-primary">{money(product.currentPrice)}</p></div><div className="text-right"><p className={`flex items-center justify-end gap-1 text-xs font-semibold ${urgent ? 'text-destructive' : 'text-secondary'}`}><Clock3 className="h-3.5 w-3.5" /> {relativeDeadline(product.endsAt, timestamp)}</p><p className="mt-1 text-[11px] text-muted-foreground">{product.condition}</p></div></div>
    </div>
  </Link>;
}

