function TrustItem({ icon: Icon, title, text }: { icon: ComponentType<{ className?: string }>; title: string; text: string }) { return <div className="flex items-start gap-3 rounded-2xl bg-[#f9f6ef]/55 p-4"><span className="grid h-9 w-9 shrink-0 place-items-center rounded-xl bg-[#f9f6ef] text-primary"><Icon className="h-4 w-4" /></span><div><p className="font-bold text-[#3b2b16]">{title}</p><p className="mt-1 text-xs leading-5 text-[#624b2d]">{text}</p></div></div>; }
function ProductSkeleton() { return <div className="grid gap-7 sm:grid-cols-2 lg:grid-cols-4">{[1, 2, 3, 4].map((item) => <div key={item}><div className="skeleton aspect-[1.08] rounded-2xl" /><div className="skeleton mt-3 h-5 w-4/5 rounded" /><div className="skeleton mt-2 h-4 w-1/2 rounded" /></div>)}</div>; }
function ErrorState() { return <div className="rounded-2xl border border-destructive/20 bg-destructive/5 p-10 text-center"><p className="font-bold">Impossible de charger les enchères</p><p className="mt-1 text-sm text-muted-foreground">Réessayez dans un instant.</p><button onClick={() => window.location.reload()} className="mt-4 rounded-full bg-primary px-4 py-2 text-sm font-bold text-primary-foreground" data-testid="button-retry">Réessayer</button></div>; }

function SearchPage() {
  const search = useSearch();
  const categories = useCategories();
  const params = new URLSearchParams(search);
  const [filters, setFilters] = useState<SearchFilters>({ query: params.get('q') ?? '', category: params.get('category') ?? '', deadline: params.get('deadline') ?? '', sort: 'recent' });
  const [showFilters, setShowFilters] = useState(false);
  const { data: products, isLoading } = useProducts(filters);
  const update = (key: keyof SearchFilters, value: string | number | undefined): void => setFilters((current) => ({ ...current, [key]: value || undefined }));
  return <main className="mx-auto max-w-[1440px] px-4 py-10 sm:px-8"><div className="mb-9 flex flex-wrap items-end justify-between gap-4"><div><p className="mb-2 text-xs font-bold uppercase tracking-[0.16em] text-secondary">Le catalogue</p><h1 className="font-display text-5xl font-bold tracking-[-0.05em]">Trouver votre prochain objet</h1><p className="mt-2 text-sm text-muted-foreground">Des pièces choisies, des enchères vivantes.</p></div><button onClick={() => setShowFilters((value) => !value)} className="flex items-center gap-2 rounded-full border border-border bg-card px-4 py-2.5 text-sm font-bold md:hidden" data-testid="button-mobile-filters"><SlidersHorizontal className="h-4 w-4" /> Filtres</button></div><div className="grid gap-10 md:grid-cols-[230px_1fr]"><aside className={`${showFilters ? 'block' : 'hidden'} md:block`}><div className="sticky top-28 space-y-7"><div className="flex items-center justify-between"><p className="font-bold">Affiner</p><button onClick={() => setFilters({ sort: 'recent' })} className="text-xs font-semibold text-primary" data-testid="button-reset-filters">Réinitialiser</button></div><FilterSelect label="Catégorie" value={filters.category ?? ''} onChange={(value) => update('category', value)} options={[{ value: '', label: 'Toutes les catégories' }, ...categories.map((category) => ({ value: category.id, label: category.name }))]} /><FilterSelect label="État" value={filters.condition ?? ''} onChange={(value) => update('condition', value)} options={[{ value: '', label: 'Tous les états' }, ...(['Neuf', 'Très bon état', 'Bon état', 'À restaurer'] as ProductCondition[]).map((condition) => ({ value: condition, label: condition }))]} /><FilterSelect label="Fin de l'enchère" value={filters.deadline ?? ''} onChange={(value) => update('deadline', value)} options={[{ value: '', label: 'Toutes les dates' }, { value: '24h', label: 'Dans les 24 heures' }]} /><FilterSelect label="Ville" value={filters.city ?? ''} onChange={(value) => update('city', value)} options={[{ value: '', label: 'Toutes les villes' }, ...Array.from(new Set((products ?? []).map((product) => product.city))).map((city) => ({ value: city, label: city }))]} /><div><label className="mb-2 block text-xs font-bold uppercase tracking-[0.1em] text-muted-foreground">Prix maximum</label><input type="number" value={filters.maxPrice ?? ''} onChange={(event) => update('maxPrice', Number(event.target.value) || undefined)} placeholder="Sans limite" className="w-full rounded-xl border border-border bg-card px-3 py-2.5 text-sm outline-none focus:border-primary" data-testid="input-max-price" /></div></div></aside><section><div className="mb-5 flex items-center justify-between border-b border-border pb-4"><p className="text-sm text-muted-foreground">{isLoading ? 'Recherche en cours…' : `${products?.length ?? 0} annonces`}</p><label className="flex items-center gap-2 text-sm font-semibold"><ArrowDownUp className="h-4 w-4 text-muted-foreground" /><select value={filters.sort ?? 'recent'} onChange={(event) => update('sort', event.target.value)} className="bg-transparent outline-none" data-testid="select-sort"><option value="recent">Plus récentes</option><option value="ending">Finissent bientôt</option><option value="price-low">Prix croissant</option><option value="price-high">Prix décroissant</option></select></label></div>{isLoading ? <ProductSkeleton /> : products && products.length ? <div className="grid gap-x-6 gap-y-10 sm:grid-cols-2 lg:grid-cols-3">{products.map((product) => <ProductCard key={product.id} product={product} compact />)}</div> : <EmptySearch />}</section></div></main>;
}
function FilterSelect({ label, value, onChange, options }: { label: string; value: string; onChange: (value: string) => void; options: { value: string; label: string }[] }) { return <div><label className="mb-2 block text-xs font-bold uppercase tracking-[0.1em] text-muted-foreground">{label}</label><select value={value} onChange={(event) => onChange(event.target.value)} className="w-full rounded-xl border border-border bg-card px-3 py-2.5 text-sm outline-none focus:border-primary" data-testid={`select-filter-${label.toLowerCase().replaceAll(' ', '-')}`}>{options.map((option) => <option key={option.value} value={option.value}>{option.label}</option>)}</select></div>; }
function EmptySearch() { return <div className="rounded-3xl border border-dashed border-border bg-card px-6 py-20 text-center"><div className="mx-auto grid h-14 w-14 place-items-center rounded-2xl bg-muted text-primary"><Search className="h-6 w-6" /></div><h2 className="mt-5 font-display text-2xl font-bold">Aucun objet dans ce coin</h2><p className="mx-auto mt-2 max-w-sm text-sm text-muted-foreground">Essayez d’élargir vos filtres. Les meilleures trouvailles aiment parfois se cacher.</p></div>; }

function ProductPage({ user }: { user: User | null }) {
  const { id = '' } = useParams<{ id: string }>();
  const { data: product, isLoading } = useProduct(id);
  const { data: bids, isLoading: bidsLoading } = useProductBids(id);
  const timestamp = useCountdown();
  const [, setLocation] = useLocation();
  const [activeImage, setActiveImage] = useState(0);
  const [tab, setTab] = useState<'description' | 'photos' | 'offres'>('description');
  const [bidOpen, setBidOpen] = useState(false);
  const [amount, setAmount] = useState(0);
  const [submitting, setSubmitting] = useState(false);
  if (isLoading) return <main className="mx-auto max-w-[1440px] px-4 py-12 sm:px-8"><ProductSkeleton /></main>;
  if (!product) return <main className="mx-auto max-w-xl px-4 py-24 text-center"><h1 className="font-display text-4xl font-bold">Objet introuvable</h1><Link href="/search" className="mt-5 inline-flex rounded-full bg-primary px-5 py-3 text-sm font-bold text-primary-foreground">Retour au catalogue</Link></main>;
  const minimum = product.currentPrice + 1;
  const submitBid = async (): Promise<void> => {
    if (!user) { setLocation(`/login?returnTo=/product/${product.id}`); return; }
    setSubmitting(true);
    try { await bidsApi.place(product.id, amount); await queryClient.invalidateQueries({ queryKey: ['product', id] }); await queryClient.invalidateQueries({ queryKey: ['bids', id] }); toast.success('Votre enchère est enregistrée'); setBidOpen(false); } catch (error) { toast.error(error instanceof Error ? error.message : 'Cette enchère n’a pas pu être enregistrée.'); } finally { setSubmitting(false); }
  };
  return <main className="mx-auto max-w-[1440px] px-4 py-8 sm:px-8"><Link href="/search" className="mb-7 inline-flex items-center gap-2 text-sm font-semibold text-muted-foreground transition hover:text-primary" data-testid="link-back-search"><ArrowLeft className="h-4 w-4" /> Retour au catalogue</Link><div className="grid gap-10 lg:grid-cols-[1.08fr_.92fr]"><div className="grid gap-3 sm:grid-cols-[82px_1fr] sm:gap-4"><div className="order-2 flex gap-2 sm:order-1 sm:flex-col">{product.images.map((image, index) => <button key={image} onClick={() => setActiveImage(index)} className={`overflow-hidden rounded-xl border-2 ${activeImage === index ? 'border-primary' : 'border-transparent'}`} data-testid={`button-gallery-${index}`}><img src={image} alt="" className="h-16 w-16 object-cover sm:h-[72px] sm:w-[72px]" /></button>)}</div><div className="relative order-1 overflow-hidden rounded-3xl bg-muted sm:order-2"><img src={product.images[activeImage]} alt={product.title} className="aspect-square w-full object-cover" data-testid={`img-product-detail-${product.id}`} /><button onClick={() => toast.success('Ajouté à vos favoris')} className="absolute right-5 top-5 grid h-11 w-11 place-items-center rounded-full bg-[#f9f6ef]/90" data-testid="button-detail-favorite"><Heart className="h-5 w-5" /></button></div></div><div className="flex flex-col"><div className="flex items-center justify-between"><span className="rounded-full bg-muted px-3 py-1.5 text-xs font-bold text-primary">{product.category.name}</span><span className="flex items-center gap-1 text-xs font-semibold text-muted-foreground"><Eye className="h-3.5 w-3.5" /> 24 personnes regardent</span></div><h1 className="mt-5 max-w-xl font-display text-4xl font-bold leading-tight tracking-[-0.05em] sm:text-5xl">{product.title}</h1><div className="mt-5 flex items-center gap-3"><span className="grid h-9 w-9 place-items-center rounded-full bg-primary text-xs font-bold text-primary-foreground">{product.seller.avatar}</span><div><p className="text-sm font-bold">{product.seller.name}</p><p className="text-xs text-muted-foreground">Vendeur à {product.city} · membre depuis 2022</p></div><ShieldCheck className="ml-2 h-5 w-5 text-primary" /></div><div className="my-7 rounded-2xl bg-[#d9ebe4] p-5"><div className="flex items-end justify-between"><div><p className="text-xs font-bold uppercase tracking-[0.14em] text-[#456a63]">Enchère actuelle</p><p className="mt-1 text-3xl font-bold text-primary">{money(product.currentPrice)}</p></div><div className="text-right"><p className={`flex items-center justify-end gap-1 text-sm font-bold ${new Date(product.endsAt).getTime() - timestamp < 3600000 ? 'text-destructive' : 'text-secondary'}`}><Clock3 className="h-4 w-4" /> {relativeDeadline(product.endsAt, timestamp)}</p><p className="mt-1 text-xs text-[#456a63]">Fin {dateLabel(product.endsAt)}</p></div></div><button onClick={() => { setAmount(minimum); setBidOpen(true); }} disabled={product.status !== 'active' || new Date(product.endsAt).getTime() <= timestamp} className="mt-5 flex w-full items-center justify-center gap-2 rounded-xl bg-primary py-3.5 text-sm font-bold text-primary-foreground transition hover:-translate-y-0.5 disabled:cursor-not-allowed disabled:opacity-50" data-testid="button-open-bid"><Gavel className="h-4 w-4" /> {product.status === 'active' && new Date(product.endsAt).getTime() > timestamp ? 'Enchérir maintenant' : 'Enchères terminées'}</button><p className="mt-3 text-center text-[11px] text-[#456a63]">Offre minimum : {money(minimum)} · paiement protégé</p></div><div className="grid grid-cols-2 gap-3 border-b border-border pb-5 text-sm"><div><p className="text-xs text-muted-foreground">Prix de départ</p><p className="mt-1 font-bold">{money(product.startPrice)}</p></div><div><p className="text-xs text-muted-foreground">État</p><p className="mt-1 font-bold">{product.condition}</p></div></div><div className="mt-6 flex gap-6 border-b border-border"><button onClick={() => setTab('description')} className={`border-b-2 pb-3 text-sm font-bold ${tab === 'description' ? 'border-primary text-primary' : 'border-transparent text-muted-foreground'}`} data-testid="tab-description">Description</button><button onClick={() => setTab('photos')} className={`border-b-2 pb-3 text-sm font-bold ${tab === 'photos' ? 'border-primary text-primary' : 'border-transparent text-muted-foreground'}`} data-testid="tab-photos">Photos</button><button onClick={() => setTab('offres')} className={`border-b-2 pb-3 text-sm font-bold ${tab === 'offres' ? 'border-primary text-primary' : 'border-transparent text-muted-foreground'}`} data-testid="tab-offers">Offres ({bids?.length ?? 0})</button></div><div className="pt-5 text-sm leading-7 text-muted-foreground">{tab === 'description' && <p>{product.description}</p>}{tab === 'photos' && <div className="grid grid-cols-2 gap-3">{product.images.map((image) => <img key={image} src={image} alt={product.title} className="aspect-square rounded-xl object-cover" />)}</div>}{tab === 'offres' && <div className="space-y-3">{bidsLoading ? <p>Chargement des offres…</p> : bids?.length ? bids.map((bid) => <div key={bid.id} className="flex items-center justify-between rounded-xl bg-muted px-4 py-3"><div><p className="font-semibold text-foreground">{bid.bidderName}</p><p className="text-xs">{dateLabel(bid.createdAt)}</p></div><p className="font-bold text-primary">{money(bid.amount)}</p></div>) : <p>Aucune offre pour le moment. Soyez le premier.</p>}</div>}</div></div></div>{bidOpen && <BidModal product={product} amount={amount} setAmount={setAmount} onClose={() => setBidOpen(false)} onSubmit={submitBid} submitting={submitting} />}</main>;
}

function BidModal({ product, amount, setAmount, onClose, onSubmit, submitting }: { product: Product; amount: number; setAmount: (value: number) => void; onClose: () => void; onSubmit: () => Promise<void>; submitting: boolean }) { const minimum = product.currentPrice + 1; const invalid = amount <= product.currentPrice; return <div className="fixed inset-0 z-50 grid place-items-center bg-[#173f3b]/55 p-4" onMouseDown={(event) => { if (event.target === event.currentTarget) onClose(); }}><div className="w-full max-w-md rounded-3xl bg-card p-6 shadow-2xl"><div className="flex items-start justify-between"><div><p className="text-xs font-bold uppercase tracking-[0.15em] text-secondary">Votre offre</p><h2 className="mt-1 font-display text-2xl font-bold">{product.title}</h2></div><button onClick={onClose} className="rounded-full p-2 hover:bg-muted" data-testid="button-close-bid"><X className="h-5 w-5" /></button></div><div className="mt-6 rounded-2xl bg-muted p-4"><div className="flex justify-between text-sm"><span className="text-muted-foreground">Prix actuel</span><strong>{money(product.currentPrice)}</strong></div><div className="mt-2 flex justify-between text-sm"><span className="text-muted-foreground">Offre minimum</span><strong className="text-primary">{money(minimum)}</strong></div></div><label className="mt-6 block text-xs font-bold uppercase tracking-[0.1em] text-muted-foreground">Votre montant</label><div className="relative mt-2"><input type="number" min={minimum} value={amount || ''} onChange={(event) => setAmount(Number(event.target.value))} className={`w-full rounded-xl border bg-card px-4 py-3 pr-16 text-lg font-bold outline-none ${invalid ? 'border-destructive' : 'border-border focus:border-primary'}`} data-testid="input-bid-amount" /><span className="absolute right-4 top-1/2 -translate-y-1/2 text-sm text-muted-foreground">$US</span></div>{invalid && <p className="mt-2 text-xs font-semibold text-destructive">Votre offre doit dépasser {money(product.currentPrice)}.</p>}<div className="mt-3 flex gap-2">{[10, 25, 50].map((increment) => <button key={increment} onClick={() => setAmount(Math.max(amount, minimum) + increment)} className="rounded-full border border-border px-3 py-1.5 text-xs font-bold hover:border-primary hover:text-primary" data-testid={`button-increment-${increment}`}>+{increment} $</button>)}</div><button disabled={invalid || submitting} onClick={() => void onSubmit()} className="mt-6 w-full rounded-xl bg-primary py-3.5 text-sm font-bold text-primary-foreground disabled:cursor-not-allowed disabled:opacity-45" data-testid="button-submit-bid">{submitting ? 'Enregistrement…' : 'Confirmer mon enchère'}</button><p className="mt-3 text-center text-[11px] text-muted-foreground">En confirmant, vous vous engagez à régler si vous remportez l’enchère.</p></div></div>; }

const loginSchema = z.object({ email: z.string().email('Entrez une adresse e-mail valide.'), password: z.string().min(6, '6 caractères minimum.') });
type LoginValues = z.infer<typeof loginSchema>;
function LoginPage({ onLogin }: { onLogin: (user: User) => void }) { const [, setLocation] = useLocation(); const returnTo = new URLSearchParams(useSearch()).get('returnTo') ?? '/account'; const [error, setError] = useState(''); const form = useForm<LoginValues>({ resolver: zodResolver(loginSchema), defaultValues: { email: '', password: '' } }); const demoAccounts = [{ user: { id: 'demo-camille', email: 'camille@exemple.fr' }, label: 'Camille Morel', description: 'Compte acheteur' }, { user: { id: 'demo-atelier', email: 'atelier@exemple.fr' }, label: 'Atelier Lune', description: 'Compte vendeur' }].map((account) => ({ ...account, password: 'marche2026' })); const submit = async (values: LoginValues): Promise<void> => { try { const user = await authApi.login(values.email, values.password); onLogin(user); toast.success('Ravi de vous revoir'); setLocation(returnTo); } catch (caught) { const message = caught instanceof Error ? caught.message : ''; setError(message === 'Invalid credentials' ? 'Adresse e-mail ou mot de passe incorrect. Si vous n’avez pas encore de compte, créez-en un.' : message || 'Connexion impossible.'); } }; return <AuthLayout eyebrow="Bon retour" title={<>Retrouvez vos<br /><em>enchères.</em></>}><form onSubmit={(event) => void form.handleSubmit(submit)(event)} className="space-y-4" data-testid="form-login"><Field label="Adresse e-mail" error={form.formState.errors.email?.message}><input {...form.register('email')} type="email" placeholder="vous@exemple.fr" className="auth-input" data-testid="input-login-email" /></Field><Field label="Mot de passe" error={form.formState.errors.password?.message}><input {...form.register('password')} type="password" placeholder="Votre mot de passe" className="auth-input" data-testid="input-login-password" /></Field>{error && <p className="rounded-xl bg-destructive/10 p-3 text-sm font-semibold text-destructive" data-testid="status-login-error">{error}</p>}<button type="submit" disabled={form.formState.isSubmitting} className="w-full rounded-xl bg-primary py-3.5 text-sm font-bold text-primary-foreground" data-testid="button-submit-login">{form.formState.isSubmitting ? 'Connexion…' : 'Se connecter'}</button><div className="rounded-2xl border border-border bg-muted/50 p-3"><p className="mb-2 text-xs font-bold uppercase tracking-[.1em] text-muted-foreground">Tester un compte de démo</p><div className="grid gap-2">{demoAccounts.map((account) => <button key={account.user.id} type="button" onClick={() => { form.setValue('email', account.user.email); form.setValue('password', account.password); setError(''); }} className="flex items-center justify-between rounded-xl bg-card px-3 py-2 text-left transition hover:border-primary hover:bg-background" data-testid={`button-demo-account-${account.user.id}`}><span><span className="block text-sm font-bold">{account.label}</span><span className="block text-xs text-muted-foreground">{account.description} · {account.user.email}</span></span><ChevronRight className="h-4 w-4 shrink-0 text-primary" /></button>)}</div><p className="mt-2 text-[11px] text-muted-foreground">Mot de passe démo : marche2026 (sans accent)</p></div><p className="pt-3 text-center text-sm text-muted-foreground">Pas encore de compte ? <Link href={`/register?returnTo=${encodeURIComponent(returnTo)}`} className="font-bold text-primary" data-testid="link-register">Créer un compte</Link></p></form></AuthLayout>; }
function AuthLayout({ eyebrow, title, children }: { eyebrow: string; title: ReactNode; children: ReactNode }) { return <main className="grid min-h-[calc(100dvh-107px)] lg:grid-cols-2"><div className="hidden bg-[#173f3b] p-12 text-[#f9f6ef] lg:flex lg:flex-col lg:justify-between"><Link href="/" className="flex items-center gap-2 font-display text-xl font-bold"><span className="grid h-9 w-9 place-items-center rounded-full bg-secondary text-foreground"><Gavel className="h-5 w-5" /></span> Marché aux enchères</Link><div><p className="mb-4 text-xs font-bold uppercase tracking-[0.2em] text-[#f7df9d]">{eyebrow}</p><h1 className="font-display text-6xl font-bold leading-[.95] tracking-[-0.06em]">{title}</h1><p className="mt-6 max-w-sm text-sm leading-6 text-[#bfd1ca]">Des objets choisis avec soin, des enchères en toute confiance.</p></div><p className="text-xs text-[#9fbdb4]">Un objet peut changer de main, pas de valeur.</p></div><div className="flex items-center justify-center px-4 py-12"><div className="w-full max-w-md"><Link href="/" className="mb-10 flex items-center gap-2 font-display text-xl font-bold lg:hidden" data-testid="link-auth-logo"><span className="grid h-9 w-9 place-items-center rounded-full bg-secondary text-foreground"><Gavel className="h-5 w-5" /></span> Marché aux enchères</Link><div className="mb-8"><p className="mb-2 text-xs font-bold uppercase tracking-[0.16em] text-secondary">{eyebrow}</p><h2 className="font-display text-4xl font-bold tracking-[-0.04em]">{title}</h2></div>{children}</div></div></main>; }
function Field({ label, error, children }: { label: string; error?: string; children: ReactNode }) { return <div><label className="mb-2 block text-xs font-bold uppercase tracking-[0.1em] text-muted-foreground">{label}</label>{children}{error && <p className="mt-1 text-xs font-semibold text-destructive">{error}</p>}</div>; }

const registerSchema = z.object({ name: z.string().min(2, 'Votre nom est requis.'), email: z.string().email('Entrez une adresse e-mail valide.'), password: z.string().min(6, '6 caractères minimum.'), city: z.string().min(2, 'Votre ville est requise.') });
type RegisterValues = z.infer<typeof registerSchema>;
function RegisterPage({ onLogin }: { onLogin: (user: User) => void }) { const [, setLocation] = useLocation(); const form = useForm<RegisterValues>({ resolver: zodResolver(registerSchema), defaultValues: { name: '', email: '', password: '', city: '' } }); const submit = async (values: RegisterValues): Promise<void> => { const user = await authApi.register(values.name, values.email, values.password, values.city); onLogin({ ...user, city: values.city }); toast.success('Votre compte est créé'); setLocation('/account'); }; return <AuthLayout eyebrow="Bienvenue" title={<>Une place pour<br /><em>vos trouvailles.</em></>}><form onSubmit={(event) => void form.handleSubmit(submit)(event)} className="space-y-4" data-testid="form-register"><Field label="Nom complet" error={form.formState.errors.name?.message}><input {...form.register('name')} placeholder="Camille Morel" className="auth-input" data-testid="input-register-name" /></Field><Field label="Adresse e-mail" error={form.formState.errors.email?.message}><input {...form.register('email')} type="email" placeholder="vous@exemple.fr" className="auth-input" data-testid="input-register-email" /></Field><Field label="Ville" error={form.formState.errors.city?.message}><input {...form.register('city')} placeholder="Bujumbura" className="auth-input" data-testid="input-register-city" /></Field><Field label="Mot de passe" error={form.formState.errors.password?.message}><input {...form.register('password')} type="password" placeholder="6 caractères minimum" className="auth-input" data-testid="input-register-password" /></Field><button type="submit" className="w-full rounded-xl bg-primary py-3.5 text-sm font-bold text-primary-foreground" data-testid="button-submit-register">Créer mon compte</button><p className="pt-3 text-center text-sm text-muted-foreground">Déjà membre ? <Link href="/login" className="font-bold text-primary" data-testid="link-login-register">Se connecter</Link></p></form></AuthLayout>; }

function SellPage({ user }: { user: User | null }) {
  const [, setLocation] = useLocation();
  const categories = useCategories();
  const [preview, setPreview] = useState(false);
  const [selectedImages, setSelectedImages] = useState<File[]>([]);
  const [imagePreviews, setImagePreviews] = useState<string[]>([]);
  const form = useForm<{ title: string; description: string; categoryId: string; condition: ProductCondition; startPrice: number; city: string; endsAt: string }>({
    defaultValues: {
      title: '', description: '', categoryId: categories[0]?.id || '', condition: 'Très bon état',
      startPrice: 50, city: user?.city ?? 'Bujumbura', endsAt: new Date(Date.now() + 7 * 86400000).toISOString().slice(0, 16),
    },
  });

  useEffect(() => {
    const urls = selectedImages.map((file) => URL.createObjectURL(file));
    setImagePreviews(urls);
    return () => urls.forEach((url) => URL.revokeObjectURL(url));
  }, [selectedImages]);

  useEffect(() => {
    const firstCategory = categories[0];
    if (firstCategory && !form.getValues('categoryId')) {
      form.setValue('categoryId', firstCategory.id, { shouldValidate: true });
    }
  }, [categories, form]);

  const addImages = (files: FileList | null): void => {
    if (!files) return;
    const chosenFiles = Array.from(files);
    const validFiles = chosenFiles.filter((file) => file.type.startsWith('image/') && file.size <= 5 * 1024 * 1024);
    if (chosenFiles.some((file) => !file.type.startsWith('image/'))) toast.error('Choisissez uniquement des fichiers image.');
    if (chosenFiles.some((file) => file.size > 5 * 1024 * 1024)) toast.error('Chaque photo doit faire 5 Mo maximum.');
    setSelectedImages((current) => {
      const combined = [...current, ...validFiles];
      if (combined.length > 10) toast.error('Vous pouvez ajouter jusqu’à 10 photos.');
      return combined.slice(0, 10);
    });
  };

  const submit = async (values: { title: string; description: string; categoryId: string; condition: ProductCondition; startPrice: number; city: string; endsAt: string }): Promise<void> => {
    if (!selectedImages.length) {
      toast.error('Choisissez au moins une photo dans votre galerie.');
      return;
    }
    if (new Date(values.endsAt).getTime() <= Date.now()) {
      toast.error('Choisissez une date future.');
      return;
    }
    try {
      const images = await productsApi.uploadImages(selectedImages);
      const condition = ({ 'Neuf': 'Neuf', 'Très bon état': 'Tres_bon_etat', 'Bon état': 'Bon_etat', 'À restaurer': 'A_restaurer' } as const)[values.condition];
      const product = await productsApi.create({ ...values, condition, startPrice: Number(values.startPrice), endsAt: new Date(values.endsAt).toISOString(), images });
      await queryClient.invalidateQueries({ queryKey: ['products'] });
      toast.success('Votre objet est en ligne');
      setLocation(`/product/${product.id}`);
    } catch (error) {
      toast.error(error instanceof Error ? error.message : 'Impossible de publier cette annonce.');
    }
  };

  if (!user) return <main className="mx-auto max-w-xl px-4 py-24 text-center"><div className="mx-auto grid h-16 w-16 place-items-center rounded-2xl bg-muted text-primary"><LogIn className="h-7 w-7" /></div><h1 className="mt-6 font-display text-4xl font-bold">Connectez-vous pour vendre</h1><p className="mt-3 text-muted-foreground">Créer une annonce prend moins de deux minutes.</p><Link href="/login?returnTo=/sell" className="mt-7 inline-flex rounded-full bg-primary px-5 py-3 font-bold text-primary-foreground" data-testid="link-login-sell">Se connecter</Link></main>;

  return <main className="mx-auto max-w-[1100px] px-4 py-10 sm:px-8">
    <div className="mb-9"><p className="mb-2 text-xs font-bold uppercase tracking-[0.16em] text-secondary">Vendre un objet</p><h1 className="font-display text-5xl font-bold tracking-[-0.05em]">Donnez-lui une nouvelle histoire.</h1><p className="mt-3 max-w-xl text-muted-foreground">Une description précise, de belles photos, et votre objet trouve son prochain propriétaire.</p></div>
    <div className="grid gap-10 lg:grid-cols-[1fr_330px]">
      <form onSubmit={(event) => { void form.handleSubmit(() => setPreview(true))(event); }} className="space-y-5" data-testid="form-sell">
        <Field label="Titre de l'annonce" error={form.formState.errors.title?.message}><input {...form.register('title', { required: 'Saisissez un titre.' })} placeholder="Ex. Lampe Art déco en opaline" className="auth-input" data-testid="input-listing-title" /></Field>
        <Field label="Description" error={form.formState.errors.description?.message}><textarea {...form.register('description', { required: 'Saisissez une description.', minLength: { value: 10, message: 'La description doit contenir au moins 10 caractères.' } })} rows={6} placeholder="Racontez l’histoire, l’état, les détails importants…" className="auth-input resize-none" data-testid="input-listing-description" /></Field>
        <div className="grid gap-4 sm:grid-cols-2"><Field label="Catégorie" error={form.formState.errors.categoryId?.message}><select {...form.register('categoryId', { required: 'Choisissez une catégorie.' })} className="auth-input" data-testid="select-listing-category"><option value="">Choisir une catégorie</option>{categories.map((category) => <option key={category.id} value={category.id}>{category.name}</option>)}</select></Field><Field label="État"><select {...form.register('condition')} className="auth-input" data-testid="select-listing-condition"><option>Neuf</option><option>Très bon état</option><option>Bon état</option><option>À restaurer</option></select></Field></div>
        <div className="grid gap-4 sm:grid-cols-2"><Field label="Prix de départ ($US)"><input {...form.register('startPrice', { valueAsNumber: true })} type="number" min={1} className="auth-input" data-testid="input-listing-price" /></Field><Field label="Ville"><input {...form.register('city')} className="auth-input" data-testid="input-listing-city" /></Field></div>
        <Field label="Fin de l'enchère"><input {...form.register('endsAt')} type="datetime-local" className="auth-input" data-testid="input-listing-deadline" /></Field>
        <Field label="Photos de l'annonce (10 maximum)">
          <input type="file" accept="image/*" multiple className="sr-only" id="listing-images" data-testid="input-listing-images" onChange={(event) => { addImages(event.target.files); event.target.value = ''; }} />
          <label htmlFor="listing-images" className="flex cursor-pointer flex-col items-center justify-center rounded-2xl border-2 border-dashed border-border bg-card px-5 py-8 text-center transition hover:border-primary hover:bg-muted"><span className="rounded-full bg-muted px-4 py-2 text-sm font-bold text-primary">Choisir des photos</span><span className="mt-2 text-xs text-muted-foreground">Ouvre vos fichiers ou votre galerie · JPEG, PNG, WebP · 5 Mo maximum par photo</span></label>
          {imagePreviews.length > 0 && <div className="mt-4 grid grid-cols-2 gap-3 sm:grid-cols-4">{imagePreviews.map((src, index) => <div key={`${src}-${index}`} className="relative"><img src={src} alt={`Photo sélectionnée ${index + 1}`} className="aspect-square w-full rounded-xl object-cover" /><button type="button" onClick={() => setSelectedImages((current) => current.filter((_, itemIndex) => itemIndex !== index))} className="absolute right-2 top-2 rounded-full bg-card/90 px-2 py-1 text-xs font-bold text-destructive" aria-label={`Supprimer la photo ${index + 1}`}>Retirer</button></div>)}</div>}
        </Field>
        <div className="flex flex-wrap justify-end gap-3 pt-3"><button type="button" onClick={() => setPreview(true)} className="rounded-full border border-border px-5 py-3 text-sm font-bold" data-testid="button-preview-listing"><Eye className="mr-2 inline h-4 w-4" /> Prévisualiser</button><button type="submit" className="rounded-full bg-primary px-5 py-3 text-sm font-bold text-primary-foreground" data-testid="button-publish-listing">Publier l'annonce <ArrowRight className="ml-2 inline h-4 w-4" /></button></div>
      </form>
      <div className="rounded-3xl bg-[#d9ebe4] p-5"><p className="flex items-center gap-2 text-sm font-bold text-primary"><ShieldCheck className="h-4 w-4" /> Conseils pour mieux vendre</p><ul className="mt-5 space-y-4 text-sm leading-6 text-[#365953]"><li className="flex gap-2"><Check className="mt-1 h-4 w-4 shrink-0 text-primary" /> Photographiez l'objet à la lumière naturelle.</li><li className="flex gap-2"><Check className="mt-1 h-4 w-4 shrink-0 text-primary" /> Mentionnez les traces d'usage sans les cacher.</li><li className="flex gap-2"><Check className="mt-1 h-4 w-4 shrink-0 text-primary" /> Un titre précis attire les bons acheteurs.</li></ul></div>
    </div>
    {preview && <div className="fixed inset-0 z-40 overflow-y-auto bg-[#173f3b]/55 p-4 py-10"><div className="mx-auto max-w-lg rounded-3xl bg-card p-6"><div className="flex justify-between"><h2 className="font-display text-2xl font-bold">Votre annonce</h2><button type="button" onClick={() => setPreview(false)} data-testid="button-close-preview"><X className="h-5 w-5" /></button></div>{imagePreviews[0] ? <div className="mt-5 overflow-hidden rounded-2xl bg-muted"><img src={imagePreviews[0]} alt="Aperçu de l'annonce" className="aspect-[1.4] w-full object-cover" /></div> : <p className="mt-5 rounded-xl bg-muted p-5 text-sm text-muted-foreground">Choisissez au moins une photo pour afficher l’aperçu.</p>}<p className="mt-4 text-xs font-bold uppercase tracking-[.12em] text-secondary">{categories.find((category) => category.id === form.getValues('categoryId'))?.name}</p><h3 className="mt-1 font-display text-3xl font-bold">{form.getValues('title') || 'Titre de votre objet'}</h3><p className="mt-2 text-sm text-muted-foreground">{form.getValues('description') || 'Votre description apparaîtra ici.'}</p><div className="mt-6 flex gap-3"><button type="button" onClick={() => setPreview(false)} className="flex-1 rounded-xl border border-border py-3 text-sm font-bold" data-testid="button-edit-preview">Modifier</button><button type="button" onClick={() => void form.handleSubmit(submit)()} className="flex-1 rounded-xl bg-primary py-3 text-sm font-bold text-primary-foreground" data-testid="button-confirm-publish">Publier</button></div></div></div>}
  </main>;
}

function AccountPage({ user }: { user: User }) { const [location] = useLocation(); const active = location.split('/')[2] ?? 'overview'; const tabs = [{ key: 'overview', label: 'Vue d’ensemble', icon: LayoutGrid, href: '/account' }, { key: 'listings', label: 'Mes annonces', icon: Package, href: '/account/listings' }, { key: 'bids', label: 'Mes enchères', icon: Gavel, href: '/account/bids' }, { key: 'earnings', label: 'Mes ventes', icon: WalletCards, href: '/account/earnings' }, { key: 'notifications', label: 'Notifications', icon: Bell, href: '/account/notifications' }, { key: 'settings', label: 'Réglages', icon: Settings2, href: '/account/settings' }]; const { data: productList = [] } = useProducts(); return <main className="mx-auto max-w-[1440px] px-4 py-9 sm:px-8"><div className="mb-9 flex flex-wrap items-center justify-between gap-4"><div className="flex items-center gap-4"><span className="grid h-16 w-16 place-items-center rounded-full bg-primary text-xl font-bold text-primary-foreground">{user.avatar}</span><div><p className="text-xs font-bold uppercase tracking-[.15em] text-secondary">Mon espace</p><h1 className="font-display text-4xl font-bold">{user.name}</h1><p className="text-sm text-muted-foreground">{user.city} · membre depuis 2025</p></div></div><Link href="/sell" className="rounded-full bg-primary px-5 py-3 text-sm font-bold text-primary-foreground" data-testid="link-account-sell"><Plus className="mr-1 inline h-4 w-4" /> Vendre un objet</Link></div><div className="grid gap-8 lg:grid-cols-[215px_1fr]"><aside><nav className="flex gap-2 overflow-x-auto pb-2 lg:grid lg:gap-1">{tabs.map(({ key, label, icon: Icon, href }) => <Link key={key} href={href} className={`flex shrink-0 items-center gap-3 rounded-xl px-3 py-2.5 text-sm font-semibold transition ${active === key ? 'bg-primary text-primary-foreground' : 'text-muted-foreground hover:bg-muted hover:text-foreground'}`} data-testid={`link-account-${key}`}><Icon className="h-4 w-4" /> {label}{key === 'notifications' && <span className={`ml-auto rounded-full px-1.5 text-[10px] ${active === key ? 'bg-primary-foreground text-primary' : 'bg-secondary text-foreground'}`}>2</span>}</Link>)}</nav></aside><section>{active === 'overview' && <Overview products={productList} />} {active === 'listings' && <Listings products={productList.filter((product) => product.seller.id === user.id)} />} {active === 'bids' && <BidsPage products={productList} user={user} />} {active === 'earnings' && <EarningsPage user={user} />} {active === 'notifications' && <NotificationsPage user={user} />} {active === 'settings' && <SettingsPage user={user} />}</section></div></main>; }
function Overview({ products }: { products: Product[] }) { return <div className="space-y-8"><div className="grid gap-4 sm:grid-cols-3"><StatCard label="Enchères en cours" value="3" icon={Gavel} tone="green" /><StatCard label="Annonces actives" value="2" icon={Package} tone="yellow" /><StatCard label="À régler" value="1" icon={CreditCard} tone="peach" /></div><div><div className="mb-4 flex items-center justify-between"><h2 className="font-display text-2xl font-bold">Vos enchères en cours</h2><Link href="/account/bids" className="text-sm font-bold text-primary">Tout voir <ChevronRight className="inline h-4 w-4" /></Link></div><div className="grid gap-4 sm:grid-cols-2">{products.slice(0, 2).map((product) => <div key={product.id} className="flex gap-4 rounded-2xl border border-border bg-card p-3"><img src={product.images[0]} alt="" className="h-24 w-24 rounded-xl object-cover" /><div><p className="line-clamp-2 font-display text-lg font-bold">{product.title}</p><p className="mt-2 text-xs text-muted-foreground">Enchère actuelle</p><p className="font-bold text-primary">{money(product.currentPrice)}</p></div></div>)}</div></div></div>; }
function StatCard({ label, value, icon: Icon, tone }: { label: string; value: string; icon: ComponentType<{ className?: string }>; tone: 'green' | 'yellow' | 'peach' }) { const colors = { green: 'bg-[#d9ebe4] text-primary', yellow: 'bg-[#f4c576] text-[#654b22]', peach: 'bg-[#f7ddd0] text-[#8d4736]' }; return <div className={`rounded-2xl p-5 ${colors[tone]}`}><div className="flex items-center justify-between"><p className="text-xs font-bold uppercase tracking-[.12em] opacity-75">{label}</p><Icon className="h-5 w-5" /></div><p className="mt-4 font-display text-4xl font-bold">{value}</p></div>; }
function Listings({ products }: { products: Product[] }) { return <div><div className="mb-5 flex items-center justify-between"><div><h2 className="font-display text-3xl font-bold">Mes annonces</h2><p className="mt-1 text-sm text-muted-foreground">Ouvrez une annonce pour consulter les offres et choisir un acheteur.</p></div><Link href="/sell" className="rounded-full border border-border px-4 py-2 text-sm font-bold" data-testid="button-manage-listings"><Plus className="mr-1 inline h-4 w-4" /> Nouvelle annonce</Link></div>{products.length ? <div className="grid gap-5 sm:grid-cols-2">{products.map((product) => <div key={product.id}><ProductCard product={product} compact /><Link href={`/account/listings/${product.id}`} className="mt-3 flex items-center justify-between rounded-xl border border-border bg-card px-4 py-3 text-sm font-bold transition hover:border-primary hover:text-primary" data-testid={`link-manage-listing-${product.id}`}><span>Voir les offres</span><ChevronRight className="h-4 w-4" /></Link></div>)}</div> : <EmptyAccount icon={Package} title="Pas encore d’annonce" text="Mettez un objet en vente et laissez les enchères commencer." action="/sell" actionLabel="Créer une annonce" />}</div>; }
function ListingOffersPage({ user }: { user: User }) {
  const { id = '' } = useParams<{ id: string }>();
  const [, setLocation] = useLocation();
  const [product, setProduct] = useState<Product>();
  const [bids, setBids] = useState<any[]>([]);
  const [payment, setPayment] = useState<any>();
  const [loading, setLoading] = useState(true);
  const refresh = async (): Promise<void> => {
    setLoading(true);
    const nextProduct = await productsApi.getById(id);
    const nextBids = await bidsApi.listByProduct(id);
    const nextPayments: any[] = [];
    setProduct(nextProduct);
    setBids(nextBids);
    setPayment(nextPayments.find((item) => item.productId === id));
    setLoading(false);
  };
  useEffect(() => { void refresh(); }, [id, user.id]);
  if (loading) return <main className="mx-auto max-w-4xl px-4 py-16 sm:px-8"><ProductSkeleton /></main>;
  if (!product || product.seller.id !== user.id) return <main className="mx-auto max-w-xl px-4 py-24 text-center"><h1 className="font-display text-4xl font-bold">Annonce inaccessible</h1><p className="mt-3 text-muted-foreground">Cette annonce n’appartient pas à ce compte vendeur.</p><Link href="/account/listings" className="mt-6 inline-flex rounded-full bg-primary px-5 py-3 font-bold text-primary-foreground">Retour à mes annonces</Link></main>;
  const retain = async (bidId: string): Promise<void> => {
    try { toast.info('Fonctionnalité à implémenter'); } catch (error) { toast.error(error instanceof Error ? error.message : 'Impossible de retenir cette offre.'); }
  };
  return <main className="mx-auto max-w-[1100px] px-4 py-10 sm:px-8"><Link href="/account/listings" className="mb-7 inline-flex items-center gap-2 text-sm font-semibold text-muted-foreground hover:text-primary"><ArrowLeft className="h-4 w-4" /> Retour à mes annonces</Link><div className="grid gap-8 lg:grid-cols-[.8fr_1.2fr]"><div><img src={product.images[0]} alt={product.title} className="aspect-square w-full rounded-3xl object-cover" /><div className="mt-5 rounded-2xl bg-muted p-5"><p className="text-xs font-bold uppercase tracking-[.13em] text-secondary">Votre annonce</p><h1 className="mt-2 font-display text-3xl font-bold">{product.title}</h1><div className="mt-4 flex items-end justify-between"><div><p className="text-xs text-muted-foreground">Offre actuelle</p><p className="text-2xl font-bold text-primary">{money(product.currentPrice)}</p></div><span className="rounded-full bg-card px-3 py-1 text-xs font-bold">{product.status === 'active' ? 'En cours' : product.status === 'sold' ? 'Vendue' : 'Terminée'}</span></div></div></div><div><p className="mb-2 text-xs font-bold uppercase tracking-[.16em] text-secondary">Gestion vendeur</p><h2 className="font-display text-4xl font-bold">Les offres reçues</h2><p className="mt-2 text-sm leading-6 text-muted-foreground">Choisissez une offre pour réserver l’objet à cet acheteur. Il recevra une notification et un délai de 24 heures pour régler.</p>{payment && <div className={`mt-6 rounded-2xl p-5 ${payment.status === 'paid' ? 'bg-[#d9ebe4]' : 'bg-[#f4c576]'}`}><p className="flex items-center gap-2 text-sm font-bold">{payment.status === 'paid' ? <Check className="h-4 w-4" /> : <CreditCard className="h-4 w-4" />} {payment.status === 'paid' ? 'Paiement reçu' : 'Vente attribuée, paiement en attente'}</p><p className="mt-2 text-sm">Montant : <strong>{money(payment.amount)}</strong></p><p className="mt-1 text-xs text-muted-foreground">{payment.status === 'paid' ? 'Vous pouvez préparer l’expédition.' : 'L’acheteur doit régler avant la fin du délai.'}</p></div>}<div className="mt-6 space-y-3">{bids.length ? bids.map((bid, index) => <div key={bid.id} className="flex flex-wrap items-center gap-3 rounded-2xl border border-border bg-card p-4"><span className={`grid h-10 w-10 place-items-center rounded-full ${index === 0 ? 'bg-secondary' : 'bg-muted'} text-sm font-bold`}>{index + 1}</span><div className="min-w-0 flex-1"><p className="font-bold">{bid.bidderName}</p><p className="text-xs text-muted-foreground">{dateLabel(bid.createdAt)} · {index === 0 ? 'offre la plus élevée' : 'offre précédente'}</p></div><p className="font-display text-xl font-bold text-primary">{money(bid.amount)}</p>{!payment && product.status === 'active' && <button onClick={() => void retain(bid.id)} className="w-full rounded-xl bg-primary px-4 py-2.5 text-sm font-bold text-primary-foreground sm:w-auto" data-testid={`button-retain-offer-${bid.id}`}>Retenir cette offre</button>}</div>) : <div className="rounded-2xl border border-dashed border-border p-8 text-center text-sm text-muted-foreground">Aucune offre reçue pour cette annonce.</div>}</div><div className="mt-6 rounded-2xl border border-border p-5"><p className="flex items-center gap-2 text-sm font-bold"><ShieldCheck className="h-4 w-4 text-primary" /> Parcours sécurisé</p><div className="mt-4 grid gap-3 text-sm sm:grid-cols-3"><span><strong>1.</strong> Vous retenez une offre</span><span><strong>2.</strong> L’acheteur est notifié</span><span><strong>3.</strong> Paiement puis expédition</span></div></div></div></div></main>;
}
function BidsPage({ products, user }: { products: Product[]; user: User }) { return <div><h2 className="mb-2 font-display text-3xl font-bold">Mes enchères</h2><p className="mb-5 text-sm text-muted-foreground">Retrouvez vos offres et les acquisitions qui vous sont attribuées.</p><EmptyAccount icon={Gavel} title="Fonctionnalité en cours d'intégration" text="Cette page sera bientôt disponible avec l'API backend." action="/search" actionLabel="Explorer les enchères" /></div>; }
function EarningsPage({ user }: { user: User }) {
  return <div><h2 className="font-display text-3xl font-bold">Mes acquisitions et ventes</h2><p className="mt-2 text-sm text-muted-foreground">Suivez les prochaines étapes côté acheteur comme côté vendeur.</p><EmptyAccount icon={WalletCards} title="Fonctionnalité en cours d'intégration" text="Cette page sera bientôt disponible avec l'API backend." action="/search" actionLabel="Explorer les enchères" /></div>;
}
function NotificationsPage({ user }: { user: User }) { const [notifications, setNotifications] = useState<any[]>([]); useEffect(() => { void usersApi.notifications().then(setNotifications).catch(() => setNotifications([])); }, [user.id]); const markRead = async (): Promise<void> => { await usersApi.markNotificationsRead(); setNotifications((current) => current.map((item) => ({ ...item, read: true }))); toast.success('Notifications marquées comme lues'); }; return <div><div className="mb-5 flex items-center justify-between"><div><h2 className="font-display text-3xl font-bold">Notifications</h2><p className="mt-1 text-sm text-muted-foreground">Les nouvelles de vos offres et de vos ventes.</p></div><button onClick={() => void markRead()} className="text-xs font-bold text-primary" data-testid="button-mark-notifications-read">Tout marquer comme lu</button></div><div className="space-y-2">{notifications.map((item) => <div key={item.id} className={`flex gap-4 rounded-2xl border p-4 ${item.read ? 'border-border bg-card' : 'border-secondary/40 bg-secondary/10'}`} data-testid={`notification-${item.id}`}><span className="grid h-10 w-10 shrink-0 place-items-center rounded-xl bg-muted text-primary">{item.type === 'bid' ? <Gavel className="h-4 w-4" /> : item.type === 'sale' ? <WalletCards className="h-4 w-4" /> : <Sparkles className="h-4 w-4" />}</span><div className="min-w-0 flex-1"><div className="flex justify-between gap-3"><p className="font-bold">{item.title}</p><span className="whitespace-nowrap text-[11px] text-muted-foreground">{dateLabel(item.createdAt)}</span></div><p className="mt-1 text-sm text-muted-foreground">{item.body}</p></div>{!item.read && <span className="mt-2 h-2 w-2 rounded-full bg-secondary" />}</div>)}</div></div>; }
function SettingsPage({ user }: { user: User }) { const [saved, setSaved] = useState(false); return <div><h2 className="font-display text-3xl font-bold">Réglages</h2><p className="mt-2 text-sm text-muted-foreground">Votre profil, vos préférences, votre tranquillité.</p><div className="mt-7 max-w-xl space-y-5"><Field label="Nom complet"><input defaultValue={user.name} className="auth-input" data-testid="input-settings-name" /></Field><Field label="Adresse e-mail"><input defaultValue={user.email} type="email" className="auth-input" data-testid="input-settings-email" /></Field><Field label="Ville"><input defaultValue={user.city} className="auth-input" data-testid="input-settings-city" /></Field><div className="rounded-2xl bg-muted p-4"><p className="font-bold">Préférences de notification</p><label className="mt-4 flex items-center justify-between text-sm"><span>Alertes quand je suis dépassé</span><input type="checkbox" defaultChecked className="h-4 w-4 accent-[hsl(var(--primary))]" data-testid="checkbox-outbid" /></label><label className="mt-3 flex items-center justify-between text-sm"><span>Rappels de fin d’enchère</span><input type="checkbox" defaultChecked className="h-4 w-4 accent-[hsl(var(--primary))]" data-testid="checkbox-deadline" /></label></div><button onClick={() => { setSaved(true); toast.success('Réglages enregistrés'); }} className="rounded-xl bg-primary px-5 py-3 text-sm font-bold text-primary-foreground" data-testid="button-save-settings">{saved ? 'Enregistré' : 'Enregistrer les réglages'}</button></div></div>; }
function EmptyAccount({ icon: Icon, title, text, action, actionLabel }: { icon: ComponentType<{ className?: string }>; title: string; text: string; action: string; actionLabel: string }) { return <div className="rounded-3xl border border-dashed border-border bg-card px-6 py-16 text-center"><div className="mx-auto grid h-14 w-14 place-items-center rounded-2xl bg-muted text-primary"><Icon className="h-6 w-6" /></div><h3 className="mt-5 font-display text-2xl font-bold">{title}</h3><p className="mx-auto mt-2 max-w-sm text-sm text-muted-foreground">{text}</p><Link href={action} className="mt-5 inline-flex rounded-full bg-primary px-4 py-2.5 text-sm font-bold text-primary-foreground" data-testid="link-empty-account-action">{actionLabel}</Link></div>; }

function NotFound() { return <main className="mx-auto max-w-xl px-4 py-24 text-center"><p className="text-xs font-bold uppercase tracking-[.16em] text-secondary">404</p><h1 className="mt-3 font-display text-5xl font-bold">Cette page s’est égarée.</h1><p className="mt-3 text-muted-foreground">Mais les belles trouvailles sont toujours dans le catalogue.</p><Link href="/search" className="mt-7 inline-flex rounded-full bg-primary px-5 py-3 font-bold text-primary-foreground">Voir les enchères</Link></main>; }

function ProtectedAccount({ user }: { user: User | null }) { if (!user) return <main className="mx-auto max-w-xl px-4 py-24 text-center"><div className="mx-auto grid h-16 w-16 place-items-center rounded-2xl bg-muted text-primary"><UserRound className="h-7 w-7" /></div><h1 className="mt-6 font-display text-4xl font-bold">Votre espace vous attend</h1><p className="mt-3 text-muted-foreground">Connectez-vous pour retrouver vos enchères et vos annonces.</p><Link href="/login?returnTo=/account" className="mt-7 inline-flex rounded-full bg-primary px-5 py-3 font-bold text-primary-foreground" data-testid="link-login-account">Se connecter</Link></main>; return <AccountPage user={user} />; }
function ProtectedListingOffers({ user }: { user: User | null }) { if (!user) return <main className="mx-auto max-w-xl px-4 py-24 text-center"><div className="mx-auto grid h-16 w-16 place-items-center rounded-2xl bg-muted text-primary"><UserRound className="h-7 w-7" /></div><h1 className="mt-6 font-display text-4xl font-bold">Connectez-vous pour gérer vos offres</h1><p className="mt-3 text-muted-foreground">Cette page est réservée au vendeur de l’annonce.</p><Link href="/login?returnTo=/account/listings" className="mt-7 inline-flex rounded-full bg-primary px-5 py-3 font-bold text-primary-foreground">Se connecter</Link></main>; return <ListingOffersPage user={user} />; }
function Router() { const { user, setUser, isLoading } = useAuthStore(); const logout = async (): Promise<void> => { await authApi.logout(); setUser(null); toast.success('À bientôt'); }; if (isLoading) return <div className="flex h-screen items-center justify-center">Chargement...</div>; return <AppShell user={user} onLogout={() => void logout()}><Switch><Route path="/" component={HomePage} /><Route path="/search" component={SearchPage} /><Route path="/product/:id"><ProductPage user={user} /></Route><Route path="/login"><LoginPage onLogin={setUser} /></Route><Route path="/register"><RegisterPage onLogin={setUser} /></Route><Route path="/sell"><SellPage user={user} /></Route><Route path="/account/listings/:id"><ProtectedListingOffers user={user} /></Route><Route path="/account"><ProtectedAccount user={user} /></Route><Route path="/account/:tab"><ProtectedAccount user={user} /></Route><Route component={NotFound} /></Switch></AppShell>; }

function App() { return <QueryClientProvider client={queryClient}><ErrorBoundary><Router /></ErrorBoundary><Toaster position="bottom-right" richColors /></QueryClientProvider>; }

export default App;
